  tryDirectHandover(token){const s=this.state,edge=token.edge,toNode=this.nodes.get(edge?.to);if(!edge||!toNode)return false;if(toNode.id===s.asrs.equipmentId)this.assignAsrsDestinationLine(token);const zone=s.asrs.zones[token.flowKey];if(!canEquipmentHandleCargo(toNode,this.layout)){if(token.blockedBy!==toNode.id)this.emit('cargo-overload',{equipmentId:toNode.id,productId:token.id,weight:cargoSpec(this.layout).weight,limit:Number(toNode.parameters?.loadCapacity)});token.blockedBy=toNode.id;return false;}token.blockedBy=null;if(!this.canAcceptNode(toNode,token,edge))return false;if(toNode.id===s.asrs.equipmentId&&(!zone||zone.inventory>=zone.capacity))return false;const entryFork=this.preselectEntryFork(token,toNode);if(entryFork&&entryFork.optionIndex===entryFork.forkIndex){token.nodeId=toNode.id;token.edge=entryFork.options[entryFork.optionIndex];token.progress=1;s.movedItems++;return true;}if(entryFork)token.preselectedRoute={nodeId:toNode.id,optionIndex:entryFork.optionIndex};const slotIndex=toNode.id===s.asrs.equipmentId?this.nextAsrsSlot(zone):0,operationDuration=cadDuration(toNode,this.layout,{slotIndex,operation:'putaway'});token.nodeId=toNode.id;token.edge=null;token.progress=token.motion?token.progress:0;token.nodeEnteredAt=s.t;token.operationDuration=operationDuration;token.readyAt=s.t+operationDuration;s.movedItems++;if(toNode.id===s.asrs.equipmentId){token.asrsPhase='putaway';token.asrsTarget=asrsTargetCell(toNode,slotIndex);s.asrs.inventory=Math.min(s.asrs.capacity,s.asrs.inventory+1);s.asrs.putaways++;if(zone){zone.inventory++;zone.putaways++;if(zone.occupiedSlots)zone.occupiedSlots[slotIndex]=true;}this.emit('asrs-putaway',{equipmentId:toNode.id,zone:token.flowKey,target:token.asrsTarget,duration:operationDuration});}this.emit('equipment-start',{equipmentId:toNode.id});return true;}
